    var visualBlocks="";
    function visualTable(caption,headers,rows){
      return '<div class="wb-visual-table-wrap"><table class="wb-visual-table"><caption>'+esc(caption)+'</caption><thead><tr>'+headers.map(function(h){return '<th>'+esc(h)+'</th>';}).join("")+'</tr></thead><tbody>'+rows.map(function(row){return '<tr>'+row.map(function(cell){return '<td>'+esc(cell)+'</td>';}).join("")+'</tr>';}).join("")+'</tbody></table></div>';
    }
    function visualChart(caption,labels,values,yLabel,note){
      var max=Math.max.apply(null,values.concat([1]))*1.15,points=values.map(function(v,i){return {x:62+i*420/Math.max(1,values.length-1),y:204-v/max*150};});
      var path=points.map(function(p,i){return (i?"L":"M")+p.x.toFixed(1)+" "+p.y.toFixed(1);}).join(" ");
      var marks=points.map(function(p,i){return '<circle cx="'+p.x+'" cy="'+p.y+'" r="5" fill="#2477a8"/><text x="'+p.x+'" y="222" text-anchor="middle" font-size="11">'+esc(labels[i])+'</text><text x="'+p.x+'" y="'+(p.y-10)+'" text-anchor="middle" font-size="11">'+esc(String(values[i]))+'</text>';}).join("");
      var svg='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 520 260"><rect width="520" height="260" rx="12" fill="#f7fafc"/><path d="M55 30 V205 H490" fill="none" stroke="#536b80" stroke-width="2"/><path d="M55 55 H490 M55 105 H490 M55 155 H490" stroke="#d8e1e9" stroke-width="1"/><text x="14" y="22" font-size="11" fill="#24364b">'+esc(yLabel)+'</text><path d="'+path+'" fill="none" stroke="#2477a8" stroke-width="3"/>'+marks+'</svg>';
      var src="data:image/svg+xml;charset=UTF-8,"+encodeURIComponent(svg);
      return '<figure class="wb-visual-chart"><img loading="eager" src="'+src+'" alt="'+esc(caption)+'"><figcaption><b>'+esc(caption)+'</b><br>'+esc(note)+'</figcaption></figure>';
    }
